import{_ as t,a0 as p,w as h,s as d,I as l,x as e,a1 as a,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何在 Linux 中啓用 Shell 腳本的調試模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中啓用 Shell 腳本的調試模式 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中啓用 Shell 腳本的調試模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中啓用 Shell 腳本的調試模式 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux","title":"如何在 Linux 中啓用 Shell 腳本的調試模式","tag":"201612","desc":""},"relativePath":"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux.md","filePath":"[post].md"}'),r={name:"201612/2016118-How-To-Enable-Shell-Script-Debugging Mode in Linux.md"};function g(b,s,k,u,c,f){const i=p("Link");return h(),d("div",null,[s[19]||(s[19]=l("h1",{id:"如何在-linux-中啓用-shell-腳本的調試模式",tabindex:"-1"},[e("如何在 Linux 中啓用 Shell 腳本的調試模式 "),l("a",{class:"header-anchor",href:"#如何在-linux-中啓用-shell-腳本的調試模式","aria-label":"Permalink to “如何在 Linux 中啓用 Shell 腳本的調試模式”"},"​")],-1)),s[20]||(s[20]=l("p",null,"腳本是存儲在一個文件的一系列命令。在終端上輸入一個個命令，按順序執行的方法太弱了，使用腳本，系統中的用户可以在一個文件中存儲所有命令，反覆調用該文件多次重新執行命令。",-1)),l("p",null,[s[1]||(s[1]=e("在 ",-1)),a(i,{href:"http://www.tecmint.com/category/bash-shell/"},{default:n(()=>[...s[0]||(s[0]=[e("學習腳本",-1)])]),_:1}),s[2]||(s[2]=e(" 或寫腳本的初期階段，我們通常從寫小腳本或者幾行命令的短腳本開始，調試這樣的腳本時我們通常無非就是通過觀察它們的輸出來確保其正常工作。",-1))]),l("p",null,[s[4]||(s[4]=e("然而，當我們開始寫非常長或上千行命令的高級腳本，例如改變系統設置的腳本，",-1)),a(i,{href:"http://www.tecmint.com/rsync-local-remote-file-synchronization-commands/"},{default:n(()=>[...s[3]||(s[3]=[e("在網絡上執行關鍵備份",-1)])]),_:1}),s[5]||(s[5]=e(" 等等，我們會意識到僅僅看腳本輸出是不足以在腳本中找到 Bug 的！",-1))]),s[21]||(s[21]=o(`<p>因此，在 Linux 系列中這篇介紹 Shell 腳本調試， 我們將看看如何啓用 Shell 腳本調試，然後在之後的系列中解釋不同的 Shell 腳本調試模式以及如何使用它們。</p><h3 id="如何開始寫一個腳本" tabindex="-1">如何開始寫一個腳本 <a class="header-anchor" href="#如何開始寫一個腳本" aria-label="Permalink to “如何開始寫一個腳本”">​</a></h3><p>一個腳本與其它文件的區別是它的首行，它包含 <code>#!</code> （She-Bang - 釋伴：定義文件類型）和路徑名（解釋器路徑），通知系統該文件是一個命令集合，將被指定程序(解釋器)解釋。</p><p>下面是不同類型腳本 <code>首行</code> 示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh          [sh 腳本]</span></span>
<span class="line"><span>#!/bin/bash        [bash 腳本] </span></span>
<span class="line"><span>#!/usr/bin/perl    [perl 程序]</span></span>
<span class="line"><span>#!/bin/awk -f      [awk 腳本]</span></span></code></pre></div><p>注意：如果腳本僅包含一組標準系統命令，沒有任何內部 Shell 指令，首行或 <code>#!</code> 可以去掉。</p><h3 id="如何在-linux-操作系統執行-shell-腳本" tabindex="-1">如何在 Linux 操作系統執行 Shell 腳本 <a class="header-anchor" href="#如何在-linux-操作系統執行-shell-腳本" aria-label="Permalink to “如何在 Linux 操作系統執行 Shell 腳本”">​</a></h3><p>調用一個腳本腳本的常規語法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ 腳本名  參數1 ... 參數N</span></span></code></pre></div><p>另一種可能的形式是明確指定將執行這個腳本的 Shell，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shell 腳本名  參數1 ... 參數N</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /bin/bash   參數1 ... 參數N     [bash 腳本]</span></span>
<span class="line"><span>$ /bin/ksh   參數1 ... 參數N      [ksh 腳本]</span></span>
<span class="line"><span>$ /bin/sh   參數1 ... 參數N       [sh 腳本]</span></span></code></pre></div><p>對於沒有 <code>#!</code> 作為首行，僅包含基礎系統命令的腳本，示例如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>### 腳本僅包含標準系統命令</span></span>
<span class="line"><span>cd /home/$USER</span></span>
<span class="line"><span>mkdir tmp</span></span>
<span class="line"><span>echo &quot;tmp directory created under /home/$USER&quot;</span></span></code></pre></div><p>使它可執行並運行，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x  腳本名</span></span>
<span class="line"><span>$ ./腳本名</span></span></code></pre></div><h3 id="啓用-shell-腳本調試模式的方法" tabindex="-1">啓用 Shell 腳本調試模式的方法 <a class="header-anchor" href="#啓用-shell-腳本調試模式的方法" aria-label="Permalink to “啓用 Shell 腳本調試模式的方法”">​</a></h3><p>下面是主要的 Shell 腳本調試選項：</p><ul><li><code>-v</code> （verbose 的簡稱） - 告訴 Shell 讀取腳本時顯示所有行，激活詳細模式。</li><li><code>-n</code> （noexec 或 no ecxecution 簡稱） - 指示 Shell 讀取所有命令然而不執行它們，這個選項激活語法檢查模式。</li><li><code>-x</code> （xtrace 或 execution trace 簡稱） - 告訴 Shell 在終端顯示所有執行的命令和它們的參數。 這個選項是啓用 Shell 跟蹤模式。</li></ul><h4 id="_1、-改變-shell-腳本首行" tabindex="-1">1、 改變 Shell 腳本首行 <a class="header-anchor" href="#_1、-改變-shell-腳本首行" aria-label="Permalink to “1、 改變 Shell 腳本首行”">​</a></h4><p>第一個機制是改變 Shell 腳本首行，如下，這會啓動腳本調試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh 選項</span></span></code></pre></div><p>其中， 選項可以是上面提到的一個或多個調試選項。</p><h4 id="_2、-調用-shell-調試選項" tabindex="-1">2、 調用 Shell 調試選項 <a class="header-anchor" href="#_2、-調用-shell-調試選項" aria-label="Permalink to “2、 調用 Shell 調試選項”">​</a></h4><p>第二個是使用如下調試選項啓動 Shell，這個方法也會打開整個腳本調試。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ shell 選項   參數1 ... 參數N</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /bin/bash 選項   參數1 ... 參數N</span></span></code></pre></div><h4 id="_3、-使用-shell-內置命令-set" tabindex="-1">3、 使用 Shell 內置命令 set <a class="header-anchor" href="#_3、-使用-shell-內置命令-set" aria-label="Permalink to “3、 使用 Shell 內置命令 set”">​</a></h4><p>第三個方法是使用內置命令 <code>set</code> 去調試一個給定的 Shell 腳本部分，如一個函數。這個機制是重要的，因為它讓我們可以去調試任何一段 Shell 腳本。</p><p>我們可以如下使用 <code>set</code> 命令打開調試模式，其中選項是之前提到的所有調試選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set 選項</span></span></code></pre></div><p>啓用調試模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set -選項</span></span></code></pre></div><p>禁用調試模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set +選項</span></span></code></pre></div><p>此外，如果我們在 Shell 腳本不同部分啓用了幾個調試模式，我們可以一次禁用所有調試模式，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ set -</span></span></code></pre></div><p>關於啓用 Shell 腳本調試模式，先講這些。正如我們看到的，我們可以調試一整個 Shell 腳本或者特定部分腳本。</p><p>在此係列下面的兩篇文章中，我們會舉例介紹如何使用 Shell 腳本調試選項，進一步瞭解 詳細（verbose）、語法檢查（syntax checking）、 跟蹤（tracing）調試模式。</p><p>更重要的是，關於這個指南，歡迎通過下面評論提出任何問題或反饋。</p><hr>`,43)),l("p",null,[s[7]||(s[7]=e("via: ",-1)),a(i,{href:"http://www.tecmint.com/enable-shell-debug-mode-linux/"},{default:n(()=>[...s[6]||(s[6]=[e("http://www.tecmint.com/enable-shell-debug-mode-linux/",-1)])]),_:1})]),l("p",null,[s[11]||(s[11]=e("作者：",-1)),a(i,{href:"http://www.tecmint.com/author/aaronkili/"},{default:n(()=>[...s[8]||(s[8]=[e("Aaron Kili",-1)])]),_:1}),s[12]||(s[12]=e(" 譯者：",-1)),a(i,{href:"https://github.com/imxieke"},{default:n(()=>[...s[9]||(s[9]=[e("imxieke",-1)])]),_:1}),s[13]||(s[13]=e(" 校對：",-1)),a(i,{href:"https://github.com/jasminepeng"},{default:n(()=>[...s[10]||(s[10]=[e("jasminepeng",-1)])]),_:1})]),l("p",null,[s[16]||(s[16]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[e("LCTT",-1)])]),_:1}),s[17]||(s[17]=e(" 組織編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[e("Linux中國",-1)])]),_:1}),s[18]||(s[18]=e(" 榮譽推出",-1))])])}const y=t(r,[["render",g]]);export{S as __pageData,y as default};
